package android.view;import java.util.*;public class ViewGroup extends View {ArrayList<View> children=new ArrayList<View>();public static class LayoutParams {public LayoutParams(int w,int h){}}public int getChildCount(){return children.size();}public View getChildAt(int i){return children.get(i);}public int indexOfChild(View v){return children.indexOf(v);}public void removeView(View v){if(children.remove(v))v.parent=null;}public void removeAllViews(){for(View v:children)v.parent=null;children.clear();}public void addView(View v){addView(v,children.size(),new LayoutParams(-1,-2));}public void addView(View v,LayoutParams p){addView(v,children.size(),p);}public void addView(View v,int i,LayoutParams p){if(v.parent!=null)throw new IllegalStateException("View already has parent");children.add(i,v);v.parent=this;}}